#!/bin/bash
# Measure Spot's acceptance encodings for the strong and weak Until formulas
# generated by mtl2tba.  The ordinary tool option is weak Until; -noweak
# generates the strong Until condition.  Each Spot call is time bounded.
# Run in WSL after run_full_eval.sh has built the tool.
HERE="$(cd "$(dirname "$0")" && pwd)"
EXE=${EXE:-"$HERE/../tool/_build/default/src/mtl2tba.exe"}
LIMIT=${LIMIT:-120}
OUT="$HERE/acceptance_results.tsv"
printf 'id\tformula\tmode\tstatus\tstates\tedges\tacc_sets\ttime_s\n' > "$OUT"
W=$(mktemp -d)
trap 'rm -rf -- "$W"' EXIT

grep -v '^#' "$HERE/formulas.tsv" | while IFS=$'\t' read -r id desc ours cas; do
  [ -z "$id" ] && continue
  for f in U W; do
    until_opt=()
    [ "$f" = U ] && until_opt=(-noweak)
    # The tool reports the intermediate formula before invoking Spot, but
    # still propagates Spot's exit status.  Use the installed translator so
    # successful extractions exit cleanly. Keep U and W independent: a strong
    # Until timeout must not discard the weak Until measurement.
    if (cd "$W" && timeout 60 "$EXE" -v -nopdf "${until_opt[@]}" \
          -o acc "$ours" > "$W/tool_$f.log" 2>&1); then
      extract_status=ok
    else
      code=$?
      extract_status=extract_error
      [ "$code" -eq 124 ] && extract_status=extract_timeout
      echo "$id $f: mtl2tba formula extraction failed"
      for mode in "-B" "-b" "--tgba"; do
        printf '%s\t%s\t%s\t%s\t\t\t\t\n' "$id" "$f" "$mode" "$extract_status" >> "$OUT"
      done
      continue
    fi
    ltl=$(sed -n 's/^clocked LTL: //p' "$W/tool_$f.log" | head -1)
    if [ -z "$ltl" ]; then
      echo "$id $f: no clocked-LTL formula in tool output"
      for mode in "-B" "-b" "--tgba"; do
        printf '%s\t%s\t%s\textract_error\t\t\t\t\n' "$id" "$f" "$mode" >> "$OUT"
      done
      continue
    fi
    printf '%s\n' "$ltl" > "$W/acc_$f.ltl"

    for mode in "-B" "-b" "--tgba"; do
      t0=$(date +%s.%N)
      r=$(timeout --kill-after=2 "$LIMIT" ltl2tgba "$mode" --small \
            --stats='%s,%e,%a' -F "$W/acc_$f.ltl" 2>/dev/null)
      code=$?
      t1=$(date +%s.%N)
      dt=$(python3 -c "print(f'{$t1-$t0:.2f}')")
      if [ "$code" -eq 0 ]; then
        IFS=, read -r states edges acc_sets <<< "$r"
        printf '%s\t%s\t%s\tok\t%s\t%s\t%s\t%s\n' \
          "$id" "$f" "$mode" "$states" "$edges" "$acc_sets" "$dt" >> "$OUT"
      else
        status=error
        [ "$code" -eq 124 ] && status=timeout
        printf '%s\t%s\t%s\t%s\t\t\t\t%s\n' "$id" "$f" "$mode" "$status" "$dt" >> "$OUT"
      fi
    done
  done
  echo "$id done"
done
column -t -s $'\t' "$OUT"
